  // Afiş / duyuru / levha: başlık + satırlar
  function AFIS(baslik, satirlar, etiket) {
    const W = 560, H = 70 + satirlar.length * 30;
    let ic = `<rect class="g-bos g-cizgi" x="20" y="8" width="520" height="${H - 16}" rx="10" stroke-width="2"/>` +
      `<rect class="g-a" x="20" y="8" width="520" height="8" rx="4"/>` + G.yazi(280, 44, baslik, { b: 1 });
    satirlar.forEach((s, i) => { ic += G.yazi(280, 78 + i * 30, s); });
    return G.svg(W, H, ic, etiket || "afiş");
  }
  // Mesajlaşma ekranı / konuşma balonları: [[kim, metin], ...] — sıra ile sola ve sağa yerleşir
  function MESAJ(mesajlar, etiket) {
    const W = 560; let y = 12, ic = "";
    mesajlar.forEach(([kim, metin], i) => {
      const sag = i % 2 === 1, w = Math.min(520, Math.max(160, 40 + metin.length * 7.8)), x = sag ? 540 - w : 20;
      ic += `<rect class="${sag ? "g-yumusak" : "g-bos"} g-cizgi" x="${x}" y="${y}" width="${w}" height="52" rx="14" stroke-width="1.5"/>` +
        G.yazi(x + 14, y + 18, kim, { a: "start", k: 1 }) + G.yazi(x + 14, y + 41, metin, { a: "start" });
      y += 64;
    });
    return G.svg(W, y, ic, etiket || "mesajlaşma ekranı");
  }
  // Not kartı: numaralı ya da düz satırlar (sola yaslı)
  function KART(baslik, satirlar, etiket) {
    const W = 560, H = 62 + satirlar.length * 28;
    let ic = `<rect class="g-yumusak g-cizgi" x="20" y="8" width="520" height="${H - 16}" rx="8" stroke-width="1.5"/>` + G.yazi(40, 36, baslik, { a: "start", b: 1 });
    satirlar.forEach((s, i) => { ic += G.yazi(40, 68 + i * 28, s, { a: "start" }); });
    return G.svg(W, H, ic, etiket || "not kartı");
  }

